using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using V15Voice;
public static class FastVoiceTests {
 static int n;static void Check(bool b,string why){if(!b)throw new Exception(why);n++;Console.WriteLine("PASS "+why);}
 static string Srt(string dir,string name,string text="This source sentence stays exactly as written."){Directory.CreateDirectory(dir);string p=Path.Combine(dir,name);File.WriteAllText(p,"1\n00:00:00,000 --> 00:00:03,200\n"+text+"\n");return p;}
 public static string WorkerRoot(){string root=Path.Combine(Path.GetTempPath(),"beo worker fixture "+Guid.NewGuid().ToString("N"));foreach(string d in new[]{"ai/models/chatter_nano","sources"})Directory.CreateDirectory(Path.Combine(root,d));foreach(string name in new[]{"t3_nano_v1.safetensors","s3gen_meanflow.safetensors","ve.safetensors","conds.pt"})File.WriteAllText(Path.Combine(root,"ai/models/chatter_nano",name),"fixture");File.WriteAllText(Path.Combine(root,"ai/ffmpeg.exe"),"fixture placeholder; Linux uses actual ffmpeg");
  File.WriteAllText(Path.Combine(root,"ai/worker.py"),@"import sys,os,base64,wave,struct,math
root=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
with open(os.path.join(root,'starts'),'a') as f:f.write('start\n')
with open(os.path.join(root,'worker-pid'),'w') as f:f.write(str(os.getpid()))
def emit(k,s):print('V15_'+k+'\t'+base64.b64encode(s.encode()).decode(),flush=True)
emit('READY','CPU fixture; not a real model')
for line in sys.stdin:
 p=line.rstrip('\n').split('\t')
 if not p or p[0]!='SYNTH':continue
 text=base64.b64decode(p[1]).decode();out=base64.b64decode(p[2]).decode();speed=float(p[3])
 with open(os.path.join(root,'requests'),'a') as f:f.write(text+'\n')
 with wave.open(out,'wb') as w:
  w.setparams((1,2,24000,0,'NONE','not compressed'))
  w.writeframes(b''.join(struct.pack('<h',int(5000*math.sin(i*.065))) for i in range(int(3*24000/speed))))
 emit('OK','CPU fixture; not a real model')
");return root;
 }
 static KokoroEngine Worker(string root){return new KokoroEngine{Root=root,Kind=EngineKind.Chatterbox,ModelFolder="chatter_nano",VoiceName="fixture",DeviceMode="cpu"};}
 static RenderOptions Options(string source,bool warm){return new RenderOptions{Locked=true,BaseSpeed=1,MinSpeed=.9,MaxSpeed=1.25,Breathing=BreathMode.None,KeepModelWarmInBatch=warm,ReportContext=new VoiceReportContext{SourcePath=source}};}
 sealed class ReleasedTranslator:ITextRewriter {public string Root;public int Calls;public string Rewrite(string prompt,Func<bool> cancel,Action<string> progress){int pid=Int32.Parse(File.ReadAllText(Path.Combine(Root,"worker-pid")));bool alive=false;try{using(var process=System.Diagnostics.Process.GetProcessById(pid))alive=!process.HasExited;}catch(ArgumentException){}if(alive)throw new IOException("TTS worker remained alive during translation");Calls++;return prompt.StartsWith("TASK=TRANSLATION_VERIFY")?"{\"items\":[{\"id\":1,\"ok\":true,\"reason\":\"fixture\"}]}":"{\"cues\":[{\"id\":1,\"text\":\"John đã mua hai quả táo.\"}]}";}}
 public static int Main(){try{
  var updates=new LatestRenderUpdate();Parallel.For(0,10000,i=>updates.Publish(i%100,"step "+i));updates.Publish(99,"last measured step");updates.Device("GPU device evidence");int value;string text,device;Check(updates.Take(out value,out text,out device)&&value==99&&text=="last measured step"&&device=="GPU device evidence","Ten thousand worker updates coalesce to the latest complete UI state");Check(!updates.Take(out value,out text,out device)&&updates.Drained==1,"Draining updates does not create repeat callbacks or a UI queue backlog");updates.Publish(100,"verified");updates.Clear();Check(!updates.Take(out value,out text,out device),"A finished/cancelled run clears pending updates before the next run");
  string root=Path.Combine(Path.GetTempPath(),"beo import "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string first=Srt(root,"story.srt"),nested=Srt(Path.Combine(root,"nested"),"story.srt");Srt(root,"story.final.srt");Srt(root,"story.aligned.srt");File.WriteAllText(Path.Combine(root,"story.voice-report.txt"),"not script");File.WriteAllText(Path.Combine(root,"notes.txt"),"not imported from folders");Srt(Path.Combine(root,"BEO_CREATOR","old"),"old.srt");
  var imported=BatchImport.Read(new[]{root,first,root},new string[0],500,()=>false);Check(imported.Jobs.Count==2&&imported.Jobs.Any(j=>j.InputPath==nested),"Folder import recursively finds source SRT files with identical names in different directories");Check(imported.Generated==2&&imported.Jobs.All(j=>j.State==JobState.Queued),"Folder import skips generated final/aligned SRT and report TXT rather than rendering outputs again");Check(imported.Duplicates>0&&imported.Jobs.Count(j=>j.InputPath==first)==1,"Repeated folders and explicit paths never duplicate a queue entry");var again=BatchImport.Read(new[]{root},imported.Jobs.Select(j=>j.InputPath),500,()=>false);Check(again.Jobs.Count==0&&again.Duplicates==2,"Existing queue paths are excluded when importing a folder again");Check(BatchImport.Read(new[]{Path.Combine(root,"story.final.srt")},new string[0],500,()=>false).Jobs.Count==1,"Explicit file import can intentionally use a final SRT as new source");Check(BatchImport.Read(new[]{root},new string[0],1,()=>false).Jobs.Count==1,"Folder import respects remaining queue capacity");bool cancelled=false;try{BatchImport.Read(new[]{root},new string[0],500,()=>true);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Folder import supports cancellation before any source queue mutation");
  string broken=Srt(root,"broken.srt");File.WriteAllText(broken,"not valid SRT");var bad=BatchImport.Read(new[]{broken},new string[0],500,()=>false);Check(bad.Jobs.Count==1&&bad.Jobs[0].State==JobState.ImportFailed,"Invalid files remain visible as individual import failures");
  var profiles=new[]{new VoiceProfile{Key="K:3",Name="Adam",Kind=EngineKind.Kokoro,Styles="Kể chuyện",Order=0},new VoiceProfile{Key="K:4",Name="Jessica",Kind=EngineKind.Kokoro,Styles="Kể chuyện|Bí ẩn / Dark curiosity",Order=1},new VoiceProfile{Key="K:5",Name="Mind",Kind=EngineKind.Kokoro,Styles="Psychology Facts / V15",Order=2},new VoiceProfile{Key="VI:1",Name="Việt",Kind=EngineKind.VieNeu,Styles="Kể chuyện",Order=3},new VoiceProfile{Key="P:1",Name="Installed Piper",Kind=EngineKind.Piper,ModelFolder="piper_john",Styles="Kể chuyện",Order=4}};
  var script=new List<Cue>{new Cue{Id=1,Start=0,End=3,Text="She opened the door and told her story."}};int checks=0;var advice=VoiceRecommendations.Analyze(script,profiles,"K:3",p=>{checks++;return true;});Check(advice.Suggestions[0].Profile.Name=="Adam"&&advice.Suggestions.All(a=>a.Profile.Kind!=EngineKind.VieNeu),"English narration preserves the selected Adam preference and excludes Vietnamese-only voices");Check(!advice.Suggestions[0].Reason.Contains("nữ")&&advice.Note.Contains("chưa đo"),"A female protagonist does not force narrator gender or claim a measured voice result");Check(checks==2,"Recommendation readiness is shared by engine/model group without loading TTS");script[0].Text="A mysterious shadow whispered about an eerie secret.";advice=VoiceRecommendations.Analyze(script,profiles,"",p=>true);Check(advice.Style=="Bí ẩn / Dark curiosity"&&advice.Suggestions[0].Profile.Name=="Jessica","Script topic matches existing voice style metadata with an explicit reason");script[0].Text="Your brain uses memory and attention to form habits.";Check(VoiceRecommendations.Analyze(script,profiles,"",p=>true).Suggestions[0].Profile.Name=="Mind","Psychology script prioritizes a voice tagged for the matching content");advice=VoiceRecommendations.Analyze(script,profiles,"K:3",p=>p.Kind==EngineKind.Piper);Check(advice.Suggestions[0].Available&&advice.Suggestions[0].Profile.Kind==EngineKind.Piper,"Installed suitable voices are offered before missing model packs");script[0].Text="Xin chào bạn, tôi đang kể một câu chuyện.";Check(VoiceRecommendations.Analyze(script,profiles,"K:3",p=>true).Suggestions.All(x=>x.Profile.Kind==EngineKind.VieNeu),"Vietnamese input uses Vietnamese voice candidates");Check(VoiceRecommendations.Analyze(new Cue[0],profiles,"K:3",p=>true).Suggestions.Count==0,"Empty imports do not produce invented voice recommendations");
  var completed=BatchJob.Load(first);string key=BatchValidity.Key("settings-a",completed);completed.RunSettingsKey=key;completed.OutputPath=Path.Combine(root,"done.wav");new Wave{Rate=24000,Samples=new short[2400]}.Write(completed.OutputPath);File.WriteAllText(Path.Combine(root,"done.final.srt"),File.ReadAllText(first));completed.ReportPath=Path.Combine(root,"done.voice-report.txt");File.WriteAllText(completed.ReportPath,"fixture");completed.State=JobState.Done;BatchValidity.Refresh(completed,key);Check(completed.State==JobState.Done,"Unchanged completed input/configuration/output remains skippable");BatchValidity.Refresh(completed,"different-settings");Check(completed.State==JobState.Queued,"Changing voice/render configuration invalidates completed-file skipping");completed.State=JobState.Done;completed.RunSettingsKey=key;File.Delete(completed.OutputPath);BatchValidity.Refresh(completed,key);Check(completed.State==JobState.Queued,"A missing WAV is rerendered instead of silently skipped as complete");File.WriteAllText(first,File.ReadAllText(first).Replace("source","updated"));completed.State=JobState.Done;BatchValidity.Refresh(completed,key);Check(completed.State==JobState.Queued&&completed.Cues[0].Text.Contains("updated"),"Edited source words are reloaded and completed status is invalidated");string state=Path.Combine(root,"queue.xml");completed.RunSettingsKey="persisted-key";QueueStore.Save(state,new[]{completed});Check(QueueStore.Load(state)[0].RunSettingsKey=="persisted-key","Render configuration fingerprint survives queue restart");
  string appearance=Path.Combine(root,"appearance.xml");File.WriteAllText(appearance,"<appearance page=\"7\" />");Check(BeoAppearance.Load(appearance).Page==1,"An old saved Creator page opens the batch queue after removal");File.WriteAllText(appearance,"<appearance page=\"900\" />");Check(BeoAppearance.Load(appearance).Page==6,"Corrupt saved page indices remain bounded to existing pages");
  completed=BatchJob.Load(first);completed.OutputPath=Path.Combine(root,"mode2.wav");new Wave{Rate=24000,Samples=new short[2400]}.Write(completed.OutputPath);File.WriteAllText(Path.Combine(root,"mode2.final.srt"),File.ReadAllText(first));completed.ReportPath=Path.Combine(root,"mode2.ai-before-after-report.txt");File.WriteAllText(completed.ReportPath,"fixture");completed.WorkflowMode=2;completed.RunSettingsKey=key;completed.State=JobState.Done;BatchValidity.Refresh(completed,key);Check(completed.State==JobState.Queued,"Missing mode-2 bilingual changes report cannot be skipped as a complete output set");
  string cache="cache-test-"+Guid.NewGuid().ToString("N");Check(ArchiveMaintenance.Due(cache)&&!ArchiveMaintenance.Due(cache),"Repeated engine construction avoids repeated cache directory scans");Check(ArchiveMaintenance.Due(cache,32L*1024*1024),"Cache maintenance is retriggered after substantial new audio writes");ArchiveMaintenance.Failed(cache);Check(ArchiveMaintenance.Due(cache),"Failed maintenance can be retried without a stale success marker");
  string warm=WorkerRoot();using(var e=Worker(warm)){for(int i=0;i<2;i++){string path=Srt(Path.Combine(warm,"sources"),"warm"+i+".srt","This is a different sentence number "+i+".");var o=Options(path,true);var result=WorkflowRunner.Run(Scripts.ParseSrt(File.ReadAllText(path)),e,o,Path.ChangeExtension(path,".wav"),1,null,(p,m)=>{});Check(result.Rendered&&result.Status=="FINAL_VERIFIED","Warm batch file "+i+" publishes actual fixture PCM and its normal one-report bundle");}Check(File.ReadAllLines(Path.Combine(warm,"starts")).Length==1&&File.ReadAllLines(Path.Combine(warm,"requests")).Length==2,"Actual external worker process is reused across two files without changing TTS requests");}
  string cold=WorkerRoot();using(var e=Worker(cold)){for(int i=0;i<2;i++){string path=Srt(Path.Combine(cold,"sources"),"cold"+i+".srt","Another source sentence number "+i+".");WorkflowRunner.Run(Scripts.ParseSrt(File.ReadAllText(path)),e,Options(path,false),Path.ChangeExtension(path,".wav"),1,null,(p,m)=>{});}}Check(File.ReadAllLines(Path.Combine(cold,"starts")).Length==2,"Legacy/nonbatch mode still releases external workers after each render");
  string translating=WorkerRoot();using(var e=Worker(translating)){string path=Srt(Path.Combine(translating,"sources"),"changed.srt","John purchased two apples.");var translator=new ReleasedTranslator{Root=translating};var o=Options(path,true);o.Translator=translator;o.TranslationCacheRoot=Path.Combine(translating,"translation");var result=WorkflowRunner.Run(Scripts.ParseSrt(File.ReadAllText(path)),e,o,Path.ChangeExtension(path,".wav"),2,(words,options,source,owner,progress)=>{var revised=VoiceRenderReport.Snapshot(words);revised[0].Text="John bought two apples.";return revised;},(p,m)=>{});Check(result.Rendered&&result.Status=="FINAL_VERIFIED"&&translator.Calls==2,"A warm batch worker is actually stopped before changed-cue translation and verification");}
  Console.WriteLine("TOTAL FAST VOICE "+n+" PASS · real file import/process/FFmpeg; synthetic TTS worker, no RTX or model claims");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
